export interface BonesParams {
  /** Segments. Default 3. 2 to 6. */
  segments?: Num;
  /** Bone 1. Default 12. Only when ik is false. */
  angle1?: Num;
  /** Bone 2. Default 12. Only when ik is false. */
  angle2?: Num;
  /** Bone 3. Default 12. Only when ik is false, segments is 3 or 4 or 5 or 6. */
  angle3?: Num;
  /** Bone 4. Default 12. Only when ik is false, segments is 4 or 5 or 6. */
  angle4?: Num;
  /** Bone 5. Default 12. Only when ik is false, segments is 5 or 6. */
  angle5?: Num;
  /** Bone 6. Default 12. Only when ik is false, segments is 6. */
  angle6?: Num;
  /** Smooth. Default 0.5. 0 to 1. */
  smooth?: Num;
  /** IK. Default false. */
  ik?: boolean;
  /** Target. Default [0.8,0.1]. In fractions of the size. Only when ik is true. */
  target?: [Num, Num];
  /** Start. Default [0,0.5]. In fractions of the size. */
  start?: [Num, Num];
  /** End. Default [1,0.5]. In fractions of the size. */
  end?: [Num, Num];
  /** Length 1. Default 1. 0.1 to 10. */
  length1?: Num;
  /** Length 2. Default 1. 0.1 to 10. */
  length2?: Num;
  /** Length 3. Default 1. 0.1 to 10. Only when segments is 3 or 4 or 5 or 6. */
  length3?: Num;
  /** Length 4. Default 1. 0.1 to 10. Only when segments is 4 or 5 or 6. */
  length4?: Num;
  /** Length 5. Default 1. 0.1 to 10. Only when segments is 5 or 6. */
  length5?: Num;
  /** Length 6. Default 1. 0.1 to 10. Only when segments is 6. */
  length6?: Num;
}

/** Bones. A chain of 2 to 6 bones from Start to End, each with its own length (relative to the others). Each bone turns on its joint (relative to the previous one) and drags what is around it; at each joint the drawing bends round an arc, keeping its thickness, and Smooth sets how long that arc is. With a Target, the angles are solved (IK) so the tip reaches it. */
