export interface CompressParams {
  /** Axis. Default "x". */
  axis?: "x" | "y";
  /** Start. Default 0.5. 0 to 1. In fractions of the size. */
  start?: Num;
  /** End. Default 0.5. 0 to 1. In fractions of the size. */
  end?: Num;
  /** Default 0.7. -1 to 1. */
  strength?: Num;
}

/** Compress. Crowds the drawing towards a center line along one axis (Strength > 0) or spreads it away from it (Strength < 0); both ends of the box stay put and the order of points is kept. The center goes from Start at one edge (top for axis x, left for axis y) to End at the other (fractions across the axis). With Rigid Pieces first, evenly spaced marks keep their shape and pile into a solid bar at the center, so a Clone grid gets a dense band that can sweep diagonally row by row. */
export function compress(params?: CompressParams, ...rest: EffectRest<CompressParams>): Effect<CompressParams>;
export function compress(name: string, params?: CompressParams, ...rest: EffectRest<CompressParams>): Effect<CompressParams>;
export function compress(...args: unknown[]): Effect<CompressParams> { return effect<CompressParams>("compress", ...(args as [])); }

export interface RopeParams {
  /** Time (s). Default 0. 0 to 100000. */
  time?: Num;
  /** Gravity. Default 1. 0 to 10. In fractions of the size. */
  gravity?: Num;
  /** Wind. Default 0. 0 to 5. */
  wind?: Num;
  /** Damping. Default 0.8. 0 to 20. */
  damping?: Num;
  /** Stiffness. Default 14. 1 to 60. */
  stiffness?: Num;
  /** Segments. Default 24. 4 to 120. */
  segments?: Num;
  /** Pointer. Default [-2,-2]. In fractions of the size. */
  pointer?: [Num, Num];
  /** Pointer in. Default "box". */
  space?: "box" | "scene";
  /** Radius. Default 0. 0 to 1. In fractions of the size. */
  radius?: Num;
  /** Settle (s). Default 0. 0 to 10. In s. */
  settle?: Num;
  /** Seed. Default 1. */
  seed?: Num;
}

/** Rope. Open paths hang as ropes pinned at both ends: a Verlet chain with the drawn length, Gravity, Wind and Damping, that settles and swings. Pointer and Radius place a round obstacle that pushes the ropes out of its way (bind Pointer to the cursor with `scene.mouse` formulas, Space set to Scene). Time follows scene.time unless it is set; keep Rope first in the stack, as it keeps its state between frames. Closed paths are left alone. */
export function rope(params?: RopeParams, ...rest: EffectRest<RopeParams>): Effect<RopeParams>;
export function rope(name: string, params?: RopeParams, ...rest: EffectRest<RopeParams>): Effect<RopeParams>;
export function rope(...args: unknown[]): Effect<RopeParams> { return effect<RopeParams>("rope", ...(args as [])); }

