export function crosshatch(...args: unknown[]): Effect<CrosshatchParams> { return effect<CrosshatchParams>("crosshatch", ...(args as [])); }

export interface DitheringParams {
  /** Cell size. Default 6. 1 to 100. In px. */
  spacing?: Num;
  /** Angle. Default 0. */
  angle?: Num;
  /** Algorithm. Default "bayer". */
  algorithm?: "bayer" | "floyd-steinberg" | "atkinson" | "noise";
  /** Bayer matrix. Default "4". Only when algorithm is bayer. */
  matrix?: "2" | "4" | "8" | "16";
  /** Threshold. Default 0.5. 0 to 1. */
  threshold?: Num;
  /** Gamma. Default 1. 0.1 to 4. */
  gamma?: Num;
  /** Invert. Default false. */
  invert?: boolean;
  /** Default 1. */
  seed?: Num;
  /** Offset. Default [0,0]. In fractions of the size. */
  offset?: [Num, Num];
  /** Merge cells. Default true. */
  merge?: boolean;
}

/** Dithering. Converts sampled tone into a binary grid of vector cells. Bayer uses an ordered 2×2 to 16×16 threshold matrix; Floyd–Steinberg and Atkinson diffuse quantization error for smoother tonal patterns; Noise uses a repeatable seeded random threshold. Cell size, angle, threshold, gamma and invert control the pattern. Cells retain sampled source colour; use Color or Tint after Dithering to style them. Merge combines contiguous cells into larger rectangles and same-colour paths. Large grids increase cell size automatically to keep sampling bounded. */
