  /** Angle. Default 0. */
  angle?: Num;
  /** Background. Default "dark". Only when mode is channels. */
  background?: "dark" | "light";
  /** Color A. Default "#00e5ff". Only when mode is duo. */
  colorA?: string;
  /** Color B. Default "#ff2bd6". Only when mode is duo. */
  colorB?: string;
  /** Layer. Default "behind". Only when mode is duo. */
  layer?: "behind" | "front";
  /** Blend. Default "normal". Only when mode is duo. */
